contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: drives c.transfer and asserts the general property
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty _tos because C.transfer requires it; if empty then transfer would revert
        require(_tos.length > 0);

        // perform the call and capture whether it reverted
        bool reverted;
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            reverted = false;
            ok = ret;
        } catch {
            reverted = true;
            ok = false;
        }

        // General property to assert:
        // If the call returned (did not revert) then it must have returned true.
        // (Additionally this implies all internal low-level calls succeeded because otherwise transfer would have reverted.)
        assert(reverted || ok == true);
    }

    receive() external payable { }
}

